def search_for_verdict(root, name, skip_depth=0):
    """Recursive search for verdict keywords"""
    max_depth = 10
    if skip_depth > max_depth:
        return
    for f in os.listdir(root):
        path = os.path.join(root, f)
        if os.path.isfile(path):
            try:
                with open(path, 'r') as fp:
                    content = fp.read()
                    # Check for verdict phrases
                    if any(kw in content.lower() for kw in ['verdict', 'correct', 'wrong', 'incorrect', 'answer']):
                        print(f"\n=== Found in: {os.path.relpath(path)} ===")
